{"explanation":"tan(x) = sin(x)/cos(x), so it's undefined wherever cos(x) = 0. That happens at x = π/2 + kπ (±π/2 and ±3π/2 on this interval), and those are the vertical asymptotes, shown as red dashed lines. Near one of them, cos(x) gets close to 0 while sin(x) stays close to ±1, so the ratio becomes huge. Coming from the left the graph shoots up toward +∞, and coming from the right it drops toward −∞. Use the slider to move the dot toward an asymptote and watch tan(x) blow up. The curve repeats every π, which is why one identical branch sits between each pair of asymptotes.","manimCode":"const PI = Math.PI;
const ax = new Axes({
  xRange: [-2*PI, 2*PI, PI/2],
  yRange: [-4, 4, 1],
  xLength: 11, yLength: 6.2, tips: false
});
ax.moveTo([0, -0.4, 0]);
scene.add(ax);

const title = new MathTex({ latex: 'y = \\tan(x) = \\frac{\\sin x}{\\cos x}', color: YELLOW });
await title.waitForRender();
title.scale(0.8);
title.moveTo([-3.6, 3.4, 0]);
scene.add(title);

// Vertical asymptotes (dashed via short segments)
const asym = [-3*PI/2, -PI/2, PI/2, 3*PI/2];
for (const a of asym) {
  const n = 20;
  for (let i = 0; i < n; i++) {
    const y0 = -4 + (8 / n) * i;
    const y1 = y0 + (8 / n) * 0.5;
    const seg = new Line({ start: ax.c2p(a, y0), end: ax.c2p(a, y1), color: RED });
    seg.setStrokeWidth(2);
    scene.add(seg);
  }
}

const asymLabel = new MathTex({ latex: '\\text{Asymptotes: } x = \\tfrac{\\pi}{2} + k\\pi \\;(\\cos x = 0)', color: RED });
await asymLabel.waitForRender();
asymLabel.scale(0.6);
asymLabel.moveTo([-3.2, 2.7, 0]);
scene.add(asymLabel);

// Tan branches, clipped where |tan x| <= 4
const eps = Math.atan(1/4);
const branches = [
  [-2*PI, -3*PI/2 - eps],
  [-3*PI/2 + eps, -PI/2 - eps],
  [-PI/2 + eps, PI/2 - eps],
  [PI/2 + eps, 3*PI/2 - eps],
  [3*PI/2 + eps, 2*PI]
];
for (const r of branches) {
  const c = ax.plot(x => Math.tan(x), { color: BLUE, xRange: r, numSamples: 300 });
  await scene.play(new Create(c));
}

// Interactive dot
let xv = 0.5;
const dot = new Dot({ point: ax.c2p(xv, Math.tan(xv)), color: YELLOW });
dot.addUpdater(() => {
  const t = Math.tan(xv);
  const yc = Math.max(-4, Math.min(4, t));
  dot.moveTo(ax.c2p(xv, yc));
  dot.setOpacity(Math.abs(t) > 4 ? 0.25 : 1);
});
scene.add(dot);

let readout = null;
async function updateReadout() {
  const s = Math.sin(xv), c = Math.cos(xv), t = Math.tan(xv);
  const tStr = Math.abs(t) > 1e4 ? '\\text{undefined}' : t.toFixed(2);
  const fresh = new MathTex({ latex: 'x=' + xv.toFixed(2) + ',\\; \\sin x=' + s.toFixed(2) + ',\\; \\cos x=' + c.toFixed(2) + ',\\; \\tan x=' + tStr, color: WHITE });
  await fresh.waitForRender();
  fresh.scale(0.55);
  fresh.moveTo([0, -3.75, 0]);
  if (readout) scene.remove(readout);
  readout = fresh;
  scene.add(readout);
}
await updateReadout();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'x', min: -6.28, max: 6.28, value: 0.5, step: 0.01, onChange: (v) => { xv = v; updateReadout(); } });

